      "critique": "# 摄影点评：院落建筑入口\n\n## 一句话总评\n\n这张照片能把院落、竹子和建筑入口记录清楚，但画面过曝区域太抢眼，主角也不够集中，所以更像随手记录而不是有明确表达的建筑照片。\n\n## 评分前检查\n\n- 硬伤判断：没有明显手抖或失焦；主要问题是高光过曝、透视偏斜、主体不明确。\n- 是否可能是故意处理：高光发白没有形成“明亮、通透、极简”的完整风格，右侧墙面细节丢失较多，更像曝光控制不足，不按故意高调处理。\n- 封顶依据：存在基础问题但画面仍可辨识，整体不应超过 5 分段中位。\n\n## 五项评分\n\n- 技术：5.4/10\n- 构图：5.0/10\n- 光线：4.5/10\n- 叙事：4.8/10\n- 总体：5.0/10\n\n## 封顶规则\n\n- 高光墙面明显溢出，光线项压到 4.5。\n- 主体不清楚：入口、竹子、建筑窗格、垃圾桶都在争夺注意力，总体封顶 5.0。\n\n## 做得好的地方\n\n- 建筑斜线有一定纵深，左侧墙面能把视线带向中间入口。\n- 竹子提供了环境层次，让画面不是单纯的墙面记录。\n- 清晰度基本够，窗框、墙砖和地面纹理都能看清。\n\n## 优先修改项\n\n### 1. 右侧过曝太强\n\n- 问题：右上和右侧墙面亮到接近发白，视觉重心被亮部抢走。\n- 为什么：建筑照片里亮部通常会先吸引眼睛；一旦亮部没有细节，画面会显得廉价、刺眼。\n- 下次怎么拍：对着右侧亮墙点一下测光，或手动降低曝光 0.7 到 1.3 档，再后期提暗部。\n- 这张怎么修：降低高光和白色色阶，右侧局部加一个渐变压暗；如果细节已经没了，不要强拉，直接裁掉一部分右侧亮墙。\n\n### 2. 主体入口没有被强调\n\n- 问题：画面里入口、窗户、竹子、垃圾桶、地面同时出现，但没有一个明确主角。\n- 为什么：新手建筑照最常见的问题不是“没东西”，而是“所有东西都差不多重要”。\n- 下次怎么拍：先决定拍“入口”还是拍“院落空间”。如果拍入口，向前走几步，让入口占画面更大比例，并避开左下垃圾桶。\n- 这张怎么修：从左下和右侧裁切，保留左墙斜线、中间入口和少量竹子，让视觉更集中。\n\n### 3. 垂直线和机位不够干净\n\n- 问题：楼体边线有轻微倾斜，地面占比偏大。\n- 为什么：建筑照片对线条很敏感，轻微歪斜会让照片显得像记录照。\n- 下次怎么拍：手机保持水平，打开网格线；站稳后先对齐建筑竖线，再按快门。\n- 这张怎么修：做透视校正，略微旋转；裁掉底部约 15%-20% 的空地。\n\n## 建议设置\n\n看不出真实 EXIF，以下是估计：\n\n- 手机/相机：优先用广角端，但不要贴得太近，避免建筑边缘变形。\n- 曝光：遇到白墙和阳光，曝光补偿约 -0.7EV 到 -1EV。\n- 对焦：点在入口附近的墙面或窗框，保证建筑主体清楚。\n- 拍摄时间：避开正午或强烈侧顶光，阴天、清晨、傍晚更适合拍这种灰砖建筑。\n\n## 后期步骤\n\n1. 先校正垂直线和轻微倾斜。\n2. 裁掉左下垃圾桶和底部过多地面，右侧亮墙也适当减少。\n3. 降低高光、白色色阶，略提阴影。\n4. 增加一点中间调对比和清晰度，让砖墙纹理更稳定。\n5. 轻微降低蓝色/青色饱和度，避免阴影发冷发灰。\n\n## 下一次练习任务\n\n同样找一个建筑入口，连续拍三张：一张只拍入口，一张把入口和环境一起拍，一张用前景植物框住入口。拍完后只选“主角最明确”的那张。\n\n## 归档路径\n\n`/Users/bytedance/Documents/摄影学习/data/archive/20260609-152803-23924196/`\n"
