      "critique": "# 摄影点评：街边楼房记录\n\n## 一句话总评\n\n这张能看清街边楼房，但中央路灯杆成了最醒目的元素，主体和观看理由都比较弱。\n\n## 评分前检查\n\n- 主体判断：可能想拍街边老楼和树列，但主体不明确。\n- 基础硬伤：没有严重虚焦；主要硬伤是主体弱和强干扰。\n- 意图判断：目前更像环境记录，摄影提炼不足。\n\n## 五项评分\n\n- 技术：5.8/10\n- 构图：4.5/10\n- 光线：5.0/10\n- 叙事：4.5/10\n- 总体：4.7/10\n\n## 封顶规则\n\n主体存在但不清楚，且中央路灯杆是主导干扰；构图、叙事和总体按 5 分以下处理。\n\n## 做得好的地方\n\n- 曝光没有严重失败，楼体和树木可辨认。\n- 横向记录了街道、树列和建筑关系。\n- 树影有一点层次。\n\n## 优先修改项\n\n1. 问题：中央路灯杆抢主体。\n   为什么：它居中、垂直、最清楚，会成为画面主角。\n   下次怎么拍：左右移动，让路灯杆离开画面中心或直接避开。\n   这张怎么修：裁掉中间路灯很难，只能改裁局部楼窗或树影。\n\n2. 问题：主体不明确。\n   为什么：楼、树、路、绿篱平均出现，没有重点。\n   下次怎么拍：只拍一个有特点的窗、一段树影或一栋楼的入口。\n   这张怎么修：裁成右侧某一段楼窗和树影，放弃全景。\n\n3. 问题：光线平且略灰。\n   为什么：没有方向光时，建筑立面缺少质感。\n   下次怎么拍：等斜光打到墙面或树影更清楚时拍。\n   这张怎么修：增加一点对比和纹理，压高光。\n\n## 建议设置\n\n看不出真实 EXIF，以下是估计：街边建筑可用 ISO 100-400、快门 1/125s 以上。更重要的是移动位置，避开正中杂物。\n\n## 后期步骤\n\n1. 裁切到局部，避开中央路灯杆。\n2. 高光 -10，对比 +8。\n3. 楼面纹理 +8。\n4. 绿色饱和度 -5。\n5. 若保留全景，适当压暗路灯杆。\n\n## 下一次练习任务\n\n拍街边楼房时先找一个明确主体：一扇窗、一扇门、一块光影或一排树影。画面中不能有路灯杆正中穿过。\n\n## 归档路径\n\n`/Users/bytedance/Documents/摄影学习/data/archive/20260609-152540-7836367a/`\n"
