      "critique": "# 摄影点评：隔窗住宅楼窗格\n\n## 一句话总评\n\n这张有窗格重复和隔着玻璃看城市的氛围，但栏杆横切、玻璃污点和室内灯反射太强，主体观看被明显打断。\n\n## 评分前检查\n\n- 主体：窗外住宅楼的重复窗格\n- 题材：城市观察/隔窗建筑\n- 基础问题等级：严重基础问题\n- 硬伤封顶检查：中间栏杆横切主体，玻璃污点和灯光反射成为主导干扰；总体通常不超过 5。\n- 高分资格：不具备。图案感存在，但基础观看被遮挡和反射破坏。\n- 故意处理判断：玻璃污点可能带来隔窗感，但栏杆和灯光反射没有形成有效结构，按干扰处理。\n\n## 五项评分\n\n- 技术：4.9/10\n- 构图：4.5/10\n- 光线：5.0/10\n- 叙事：5.1/10\n- 总体：4.8/10\n\n## 封顶规则\n\n主体被栏杆、玻璃污点和室内灯反射明显干扰；多个主要干扰同时出现，因此构图和总体被封顶。\n\n## 做得好的地方\n\n- 红砖楼和灰色窗格有重复节奏，适合做图案化观察。\n- 画面曝光基本可读，没有严重过曝到完全丢失楼体信息。\n- 玻璃上的痕迹让照片有一点“隔着窗看外面”的生活感。\n\n## 优先修改项\n\n### 1. 栏杆横切主体\n\n- 问题：画面中下部的粗栏杆横穿整张照片。\n- 为什么：它比楼体窗格更亮、更粗，会把观众视线直接拦住。\n- 下次怎么拍：抬高或降低机位，让栏杆离开楼体主体区域；如果避不开，就只拍栏杆上方的部分。\n- 这张怎么修：裁掉栏杆以下区域，改成只保留上方楼体和窗格。\n\n### 2. 玻璃污点和反射太多\n\n- 问题：窗面灰尘、划痕和室内灯反射覆盖在主体上。\n- 为什么：隔窗拍摄可以保留一点反射，但反射不能比主体更抢眼。\n- 下次怎么拍：镜头贴近玻璃，关掉室内灯或用身体挡住反光。\n- 这张怎么修：降低高光，局部压暗灯光反射，减少污点清晰度。\n\n### 3. 图案没有被进一步提炼\n\n- 问题：楼体窗格有节奏，但画面还包含太多边缘反射和树枝。\n- 为什么：图案摄影需要简化，让重复关系成为唯一重点。\n- 下次怎么拍：用更长焦或裁切，只拍一块完整的窗格矩阵。\n- 这张怎么修：裁成正方形或偏横画幅，只保留最整齐的一组窗格。\n\n## 建议设置\n\n看不出实际相机、镜头和曝光参数，以下是估计建议：\n\n- 手机：用 2x 或 3x 拍窗格局部，镜头贴玻璃，点楼体对焦并略降曝光。\n- 相机：建议 f/5.6-f/8、ISO 100-800、快门 1/125s 以上；隔窗拍摄后要放大确认焦点在窗外楼体。\n- 光线：优先选择室内暗、室外亮但不过曝的时刻，减少室内反射。\n\n## 后期步骤\n\n1. 裁掉栏杆以下区域，先解决最大干扰。\n2. 做轻微透视和水平校正，让窗格更规整。\n3. 压低灯光反射高光，避免它们成为视觉中心。\n4. 提升楼体窗格的局部对比。\n5. 适度降低玻璃污点清晰度，只保留少量隔窗氛围。\n\n## 下一次练习任务\n\n拍 6 张隔窗建筑：3 张镜头贴玻璃减少反射，3 张故意保留一点反射。每张都必须满足一个条件：不能有栏杆或窗框横切主体。\n\n归档路径：/Users/bytedance/Documents/摄影学习/data/archive/20260609-110023-d97bc8e2/\n原图：original.jpg\n"
