      "id": "20260609-1046-8fc0e0fd",
      "title": "摄影点评：透明贴纸包装记录",
      "createdAt": "2026-06-09T10:46:00+08:00",
      "dateKey": "2026-06-09",
      "imageSrc": "../data/archive/20260609-1046-8fc0e0fd/original.jpg",
      "imageFile": "original.jpg",
