      "critique": "# 摄影点评：阳台栏杆上的猫\n\n## 一句话总评\n\n这张照片抓到了猫看向镜头的瞬间，生活感不错，但拍摄距离偏远、下方红墙空白过大，猫的表情没有被充分放大。\n\n## 评分前检查\n\n- 可见基础硬伤：没有明显手抖或严重虚焦；猫的眼睛、毛色和栏杆都能辨认。\n- 主要问题：主体猫占比偏小；下方红墙面积过大；栏杆、管道和砖墙线条较杂。\n- 是否属于故意处理：仰拍阳台猫有现场感，但大面积红墙和杂线不像刻意构图。\n\n## 五项评分\n\n- 技术：6.2/10\n- 构图：5.8/10\n- 光线：5.9/10\n- 叙事：6.5/10\n- 总体：6.1/10\n\n## 封顶规则\n\n没有触发基础硬伤封顶。猫的眼神和主体识别都成立，可以高于普通随手记录；但主体比例偏小和下方空白限制总体不宜超过 6.5。\n\n## 做得好的地方\n\n- 猫正看镜头，眼神是这张照片最有效的部分。\n- 砖墙、栏杆和阳台提供了真实生活环境。\n- 猫的毛色在浅色栏杆和红墙之间有一定分离度。\n\n## 优先修改项\n\n### 1. 猫占比太小\n\n- 问题：猫在画面中偏小，表情和毛发细节没有成为绝对重点。\n- 为什么：动物照片最打动人的通常是眼神、表情和姿态，主体太小会削弱吸引力。\n- 下次怎么拍：在不打扰猫的前提下靠近，或用 2x/3x 焦段拍。\n- 这张怎么修：裁成更紧的横构图，让猫和栏杆占据画面中心。\n\n### 2. 下方红墙空白太大\n\n- 问题：红墙占据了大量前景，但信息较少。\n- 为什么：大色块可以稳定画面，但这里压缩了猫的存在感。\n- 下次怎么拍：抬高取景，让红墙只作为底部一条色块。\n- 这张怎么修：裁掉底部约 35%-45% 红墙，让猫更靠近画面下三分线。\n\n### 3. 背景线条较杂\n\n- 问题：栏杆、管道、窗户和砖缝线条很多，容易分散注意力。\n- 为什么：动物主体已经不大，背景线条越复杂，主体越容易被淹没。\n- 下次怎么拍：换角度让猫背后背景更干净，或者等猫移动到更开阔的位置。\n- 这张怎么修：降低砖墙和管道的清晰度，局部提亮猫脸。\n\n## 建议设置\n\n看不出真实 EXIF，以下是估计：\n\n- 动物静态：ISO 100-400。\n- 快门：至少 1/250s；如果猫在移动，建议 1/500s 以上。\n- 焦段：手机建议 2x 或 3x，避免主体太小。\n- 对焦：点按猫的眼睛或脸部。\n\n## 后期步骤\n\n1. 大幅裁掉底部红墙，保留少量作为色块。\n2. 局部提亮猫脸和眼睛。\n3. 降低砖墙、管道和栏杆的清晰度。\n4. 稍微增加猫毛发的局部对比。\n5. 检查裁切后猫的前方是否留有一点空间，不要把脸贴边。\n\n## 下一次练习任务\n\n拍高处的猫时，练习“主体占比”：同一只猫拍三张，分别让猫占画面 10%、25%、40%。比较哪张最能看到眼神。\n\n## 归档路径\n\n`/Users/bytedance/Documents/摄影学习/data/archive/20260604-212440-balcony-cat-brick-wall/`\n"
