      "critique": "# 摄影点评：夜港山城灯火\n\n## 一句话总评\n\n这张照片有港口、船、水面倒影和山坡灯火，夜景氛围不错，但黑色天空占比过大，局部灯光高光溢出，画面略显散。\n\n## 评分前检查\n\n- 可见基础硬伤：没有严重手抖或完全失焦；船、建筑和灯光可辨。\n- 主要问题：天空黑区过多；灯光高光有溢出；前景船和山坡灯火之间主次略不清。\n- 是否属于故意处理：夜空留黑有氛围作用，但目前比例偏大，不完全服务主体。\n\n## 五项评分\n\n- 技术：6.2/10\n- 构图：6.3/10\n- 光线：6.4/10\n- 叙事：6.8/10\n- 总体：6.5/10\n\n## 封顶规则\n\n没有触发严重基础硬伤封顶。夜景主体可读，港口故事感明确；但高光溢出、黑天空过多和主次不够集中，让总体限制在 6.5 左右。\n\n## 做得好的地方\n\n- 前景船只提供了明确的观看入口。\n- 山坡灯火形成层层上升的空间感。\n- 水面倒影增强了夜景气氛。\n\n## 优先修改项\n\n### 1. 天空黑区太大\n\n- 问题：上半部分大面积接近纯黑，信息很少。\n- 为什么：夜景留黑可以有氛围，但过多会压缩主体内容。\n- 下次怎么拍：把取景向下移，多收水面倒影和船，减少纯黑天空。\n- 这张怎么修：裁掉上方约 25%-35% 黑天空，让山坡灯火和港口更突出。\n\n### 2. 高光控制不足\n\n- 问题：部分灯光和船边亮点已经刺眼，细节丢失。\n- 为什么：夜景最亮点容易抢走视线，高光失控会让画面显脏。\n- 下次怎么拍：减 0.7-1 档曝光，后期再提暗部。\n- 这张怎么修：降低高光和白色色阶，局部压暗最亮灯点。\n\n### 3. 主体关系略散\n\n- 问题：前景船、左侧码头、山坡建筑、水面倒影都很多，但没有唯一中心。\n- 为什么：夜景信息多时更需要明确主角。\n- 下次怎么拍：可以只围绕前景船构图，或者只拍山坡灯火和倒影。\n- 这张怎么修：裁成更宽的横幅，保留前景船和山坡灯火，减少边缘杂项。\n\n## 建议设置\n\n看不出真实 EXIF，以下是估计：\n\n- 夜景手持：ISO 800-1600 可能更常见，但噪点会增加。\n- 快门：手持至少 1/60s；有支撑时可以更慢。\n- 曝光：对最亮灯光减曝光补偿。\n- 稳定：夜景建议靠栏杆或使用三脚架，减少糊和噪点。\n\n## 后期步骤\n\n1. 裁掉上方大面积黑天空。\n2. 降低高光，控制刺眼灯点。\n3. 提升山坡建筑中间调，让层次更清楚。\n4. 对水面倒影做少量对比增强。\n5. 降噪一点，但不要把建筑和水面纹理抹平。\n\n## 下一次练习任务\n\n拍夜港时练习“少拍天空”：同一场景拍一张天空多、一张水面多、一张前景船多。比较哪张夜景信息最集中。\n\n## 归档路径\n\n`/Users/bytedance/Documents/摄影学习/data/archive/20260604-211736-night-harbor-hillside/`\n"
