      "critique": "# 摄影点评：方向异常的白色雕塑近景\n\n## 一句话总评\n\n这张照片的雕塑质感和黑白对比不错，但当前展示方向不自然，主体裁切也偏紧，首先需要解决方向和构图完整性。\n\n## 评分前检查\n\n- 可见基础硬伤：雕塑细节清楚，没有明显手抖；但画面方向显示异常，观看时需要重新理解。\n- 主要问题：方向不正；雕塑头部和身体被压在边缘；白色高光局部偏亮。\n- 是否属于故意处理：如果没有明确说明，当前方向更像文件方向/拍摄方向问题，不按有意旋转构图处理。\n\n## 五项评分\n\n- 技术：5.8/10\n- 构图：4.7/10\n- 光线：6.5/10\n- 叙事：5.6/10\n- 总体：5.1/10\n\n## 封顶规则\n\n触发展示方向问题封顶。雕塑质感本身可到 6 分以上，但方向异常会造成基础观看障碍，所以总体不宜超过 5.5。\n\n## 做得好的地方\n\n- 白色雕塑和黑色背景分离明显，主体识别很强。\n- 侧光让衣褶和头发纹理有立体感。\n- 近距离拍摄让材质细节比较清楚。\n\n## 优先修改项\n\n### 1. 先修正方向\n\n- 问题：当前画面像是横向倒置/旋转后的展示，观众需要先判断方向。\n- 为什么：方向错误会直接影响观看体验，是比后期色彩更优先的问题。\n- 下次怎么拍：拍完现场检查预览方向；导出前确认照片在相册里方向正确。\n- 这张怎么修：先按正确方向旋转，再重新判断裁切。\n\n### 2. 主体裁切太紧\n\n- 问题：雕塑身体和边缘关系紧，头部附近也缺少呼吸空间。\n- 为什么：雕塑作品需要保留轮廓和姿态，否则会像局部记录。\n- 下次怎么拍：后退一点，多留边，后期再裁。\n- 这张怎么修：如果原图没有更多画幅，只能裁成更明确的局部，例如只保留头部和肩部。\n\n### 3. 白色高光需要控制\n\n- 问题：白色雕塑局部亮度接近溢出，细节会变薄。\n- 为什么：拍白色物体时，高光一旦丢失，材质就会显得塑料化。\n- 下次怎么拍：对雕塑减 0.3-0.7 档曝光，保护白色细节。\n- 这张怎么修：降低高光和白色色阶，局部增强衣褶纹理。\n\n## 建议设置\n\n看不出真实 EXIF，以下是估计：\n\n- 室内/展陈雕塑：ISO 400-800。\n- 快门：1/125s 以上，避免手持轻微抖动。\n- 光圈：手机自动即可；相机可用 f/4-f/5.6。\n- 曝光：对白色主体减曝光补偿，宁可略暗再后期提。\n\n## 后期步骤\n\n1. 首先旋转到正确方向。\n2. 再决定是做完整雕塑照，还是裁成头肩局部。\n3. 降低白色高光，保留衣褶和头发纹理。\n4. 黑色背景轻微压暗，让主体更干净。\n5. 对雕塑面部和衣褶做少量局部清晰度。\n\n## 下一次练习任务\n\n拍白色雕塑时练习“高光保护”：同一个雕塑拍三张，正常曝光、减 0.3 档、减 0.7 档。比较哪张白色表面最有纹理。\n\n## 归档路径\n\n`/Users/bytedance/Documents/摄影学习/data/archive/20260604-211545-white-sculpture-closeup/`\n"
