      "critique": "# 摄影点评：方向异常的清真寺拱廊水景\n\n## 一句话总评\n\n这张照片的建筑线条、水景和重复拱廊很有潜力，但当前展示方向明显异常，首先需要旋正，否则会严重影响观看体验。\n\n## 评分前检查\n\n- 可见基础硬伤：画面清晰，建筑和水景细节可辨；但方向显示不正，是最主要问题。\n- 主要问题：方向错误；建筑线条因此变成不自然的横向压迫；白色建筑高光略硬。\n- 是否属于故意处理：没有明确说明时，不按刻意旋转构图处理，更像文件方向/展示方向问题。\n\n## 五项评分\n\n- 技术：6.1/10\n- 构图：5.1/10\n- 光线：6.8/10\n- 叙事：6.4/10\n- 总体：5.8/10\n\n## 封顶规则\n\n触发展示方向问题封顶。若旋正后，重复拱廊、水线和蓝天白墙关系有 7 分段潜力；但当前方向造成基础观看障碍，总体不宜超过 6 分。\n\n## 做得好的地方\n\n- 拱廊重复节奏很强，有明确建筑秩序。\n- 水景形成一条清楚的引导线。\n- 白色建筑、蓝天和金色装饰颜色关系干净。\n\n## 优先修改项\n\n### 1. 先修正方向\n\n- 问题：照片当前横置显示，建筑重力方向不对。\n- 为什么：建筑摄影最重要的是线条秩序，方向错误会直接破坏秩序。\n- 下次怎么拍：拍完立即检查相册预览，导出前确认方向正确。\n- 这张怎么修：先旋转到正确方向，再做裁切和透视调整。\n\n### 2. 透视需要精修\n\n- 问题：旋正后，建筑仍会有明显透视收束。\n- 为什么：广角拍大型建筑时，线条容易倾斜，需要后期轻微校正。\n- 下次怎么拍：退远一点，保持镜头更平，或者多留边方便后期校正。\n- 这张怎么修：旋正后做轻微透视校正，保留建筑的纵深。\n\n### 3. 白色高光略硬\n\n- 问题：白色墙体在强光下局部偏亮。\n- 为什么：白色建筑很容易丢失细节，高光过硬会削弱材质。\n- 下次怎么拍：对高光减 0.3-0.7 档曝光。\n- 这张怎么修：降低高光，增强墙面纹理和拱廊阴影层次。\n\n## 建议设置\n\n看不出真实 EXIF，以下是估计：\n\n- 白天建筑：ISO 100-200。\n- 快门：1/250s 以上。\n- 光圈：f/5.6-f/8。\n- 曝光：对白墙和天空减一点曝光补偿，保护高光。\n\n## 后期步骤\n\n1. 先旋转到正确方向。\n2. 做轻微透视校正，让拱廊和塔保持稳定。\n3. 降低白墙高光，保留石材和装饰细节。\n4. 增强水面蓝色和拱廊阴影的局部对比。\n5. 裁掉旋正后多余边缘，让水线成为明确引导线。\n\n## 下一次练习任务\n\n拍大型建筑时练习“方向和线条检查”：每拍完一张，立刻检查三件事：方向是否正确、竖线是否过歪、主体边缘是否被切。\n\n## 归档路径\n\n`/Users/bytedance/Documents/摄影学习/data/archive/20260604-211358-mosque-arcade-water/`\n"
