      "critique": "# 摄影点评：渡船上的逆光旗帜\n\n## 一句话总评\n\n这张照片有明确的旅行现场感，红白旗帜、航迹和湖面反光都很有动势，主要需要控制强逆光高光和山体暗部。\n\n## 评分前检查\n\n- 可见基础硬伤：没有明显手抖或严重虚焦；旗帜、湖面和山体轮廓清楚。\n- 主要问题：太阳和水面反光过亮；远山暗部偏重；右下人物和栏杆略杂。\n- 是否属于故意处理：逆光和旗帜动势是有效表达，不是曝光失败；但高光仍需要控制。\n\n## 五项评分\n\n- 技术：6.9/10\n- 构图：7.2/10\n- 光线：7.0/10\n- 叙事：7.5/10\n- 总体：7.2/10\n\n## 封顶规则\n\n没有触发基础硬伤封顶。主体明确、航迹引导和旅行叙事都成立，可以进入 7 分段；强高光和暗部压缩限制它不到 7.6 以上。\n\n## 做得好的地方\n\n- 红白旗帜是很醒目的视觉锚点。\n- 船尾航迹把视线带向远处山岸。\n- 水面反光增强了逆光旅行的现场感。\n\n## 优先修改项\n\n### 1. 高光太强\n\n- 问题：太阳附近和水面反光局部接近溢出。\n- 为什么：高光过强会让观众眯眼，也会削弱水面纹理。\n- 下次怎么拍：逆光时减 0.7-1 档曝光，优先保护高光。\n- 这张怎么修：降低高光和白色色阶，局部压暗水面最亮区域。\n\n### 2. 山体暗部偏重\n\n- 问题：远山层次偏暗，细节不够分开。\n- 为什么：逆光会让山体成为剪影，但如果太黑，环境信息会少。\n- 下次怎么拍：等太阳稍微偏离画面，或选择侧逆光。\n- 这张怎么修：局部提升山体阴影，保持层次但不要提成灰。\n\n### 3. 右下角略杂\n\n- 问题：人物、栏杆和船体边缘信息较多。\n- 为什么：这些元素有现场感，但太多会分散旗帜注意力。\n- 下次怎么拍：让旗帜和航迹占主角，人物只保留少量环境。\n- 这张怎么修：右下角轻裁一点，保留旗杆和少量甲板即可。\n\n## 建议设置\n\n看不出真实 EXIF，以下是估计：\n\n- 强逆光水面：ISO 100-200。\n- 快门：1/500s 以上，保证旗帜和船上人物不糊。\n- 光圈：f/5.6-f/8。\n- 曝光：对水面高光减曝光补偿。\n\n## 后期步骤\n\n1. 降低太阳和水面高光。\n2. 提升山体暗部少量层次。\n3. 对红白旗帜做局部清晰度和饱和度控制。\n4. 裁掉右下角少量杂乱甲板。\n5. 保留水面航迹的亮线，它是这张的主要引导。\n\n## 下一次练习任务\n\n在船上练习“运动引导线”：分别拍旗帜、航迹、远山三张，再拍一张把三者组合在一起的照片。比较哪张最有旅行感。\n\n## 归档路径\n\n`/Users/bytedance/Documents/摄影学习/data/archive/20260604-210720-ferry-flag-backlight/`\n"
