      "critique": "# 摄影点评：山谷湖泊与远处雪山\n\n## 一句话总评\n\n这张照片的山谷夹景、湖面延伸和远处雪山关系清楚，空间纵深很好，是一张结构不错的风景照。\n\n## 评分前检查\n\n- 可见基础硬伤：没有明显手抖或严重虚焦；山体、湖面和雪山都清楚。\n- 主要问题：光线偏硬，天空略空；前景碎石坡稍显杂乱；整体色调略灰。\n- 是否属于故意处理：山谷透视和湖面引导是有效构图，不是随手记录。\n\n## 五项评分\n\n- 技术：7.0/10\n- 构图：7.5/10\n- 光线：6.5/10\n- 叙事：7.2/10\n- 总体：7.2/10\n\n## 封顶规则\n\n没有触发基础硬伤封顶。山谷、湖面和雪山形成完整前中后景，可以进入 7 分段；光线偏硬和前景略乱限制它不到 7.7。\n\n## 做得好的地方\n\n- 两侧山体自然形成夹景，把视线导向远处雪山。\n- 湖面形状有延伸感，空间深度明确。\n- 雪山作为远景视觉落点很有效。\n\n## 优先修改项\n\n### 1. 光线偏硬\n\n- 问题：山坡和天空亮度比较平，缺少柔和层次。\n- 为什么：风景照的光线决定立体感，硬光容易让灰石坡显得干。\n- 下次怎么拍：优先选择清晨、傍晚或云层更丰富的时候。\n- 这张怎么修：降低高光，轻微提升山体中间调层次。\n\n### 2. 天空略空\n\n- 问题：天空面积不小，但云层内容少。\n- 为什么：天空没有足够纹理时，会削弱画面密度。\n- 下次怎么拍：向下取景，让湖面和山谷占更多比例。\n- 这张怎么修：裁掉上方约 10%-15% 天空。\n\n### 3. 前景碎石略乱\n\n- 问题：底部和两侧碎石坡信息比较散。\n- 为什么：前景应该引导视线，而不是让观众停留在杂乱纹理上。\n- 下次怎么拍：找一块明确石头、树枝或岸线作为前景点。\n- 这张怎么修：底部轻裁，保留湖面入口。\n\n## 建议设置\n\n看不出真实 EXIF，以下是估计：\n\n- 山水风景：ISO 100-200。\n- 快门：1/250s 以上。\n- 光圈：f/5.6-f/8。\n- 焦段：1x 保留开阔，2x 可压缩远山。\n\n## 后期步骤\n\n1. 裁掉少量天空和底部碎石。\n2. 对远处雪山轻微去雾和增强对比。\n3. 降低高光，避免灰石坡过亮。\n4. 水面增加一点对比，突出湖形。\n5. 整体略微加暖或降低灰感。\n\n## 下一次练习任务\n\n拍山谷时练习“夹景构图”：让两侧山体像门一样夹住远处主体，分别拍横构图和竖构图，比较哪张纵深更强。\n\n## 归档路径\n\n`/Users/bytedance/Documents/摄影学习/data/archive/20260604-210427-mountain-lake-valley/`\n"
