      "critique": "# 摄影点评：俯瞰城市教堂建筑群\n\n## 一句话总评\n\n这张照片有清楚的城市教堂主体和俯瞰层次，地点信息完整，但天空灰白、光线偏平，画面冲击力略弱。\n\n## 评分前检查\n\n- 可见基础硬伤：没有明显手抖或严重虚焦；建筑轮廓和屋顶细节可辨。\n- 主要问题：天空占比略大且灰白；整体光线缺少方向；边缘树枝稍杂。\n- 是否属于故意处理：树枝框景和俯拍视角成立，灰天空更像天气限制。\n\n## 五项评分\n\n- 技术：6.8/10\n- 构图：6.9/10\n- 光线：6.1/10\n- 叙事：7.0/10\n- 总体：6.8/10\n\n## 封顶规则\n\n没有触发基础硬伤封顶。主体清楚、建筑层次完整，可以进入 6.5 以上；但光线偏平和天空无内容限制总体不宜超过 7。\n\n## 做得好的地方\n\n- 绿色穹顶和钟楼是明确视觉中心。\n- 俯视角能交代城市与建筑群关系。\n- 左右树枝形成自然边框，让画面有前景层次。\n\n## 优先修改项\n\n### 1. 天空灰白偏多\n\n- 问题：天空面积较大，但缺少云层细节和色彩。\n- 为什么：无内容天空会稀释建筑主体。\n- 下次怎么拍：多向下取景，或等有云层/光线变化时拍。\n- 这张怎么修：裁掉上方约 15%-20% 天空。\n\n### 2. 光线偏平\n\n- 问题：建筑立面没有明显侧光，体积感不强。\n- 为什么：建筑照需要光影帮助分层。\n- 下次怎么拍：清晨或傍晚侧光时再拍，屋顶和塔楼会更立体。\n- 这张怎么修：局部增加建筑对比和清晰度。\n\n### 3. 边缘树枝略杂\n\n- 问题：右下和左侧树枝有框景作用，但有些分散。\n- 为什么：前景应该轻轻框住主体，不要挡住建筑细节。\n- 下次怎么拍：换一点机位，让树枝只留在边缘。\n- 这张怎么修：裁掉右下杂枝，保留左侧少量树枝作为框景。\n\n## 建议设置\n\n看不出真实 EXIF，以下是估计：\n\n- 城市建筑：ISO 100-200。\n- 快门：1/250s 以上。\n- 光圈：f/5.6-f/8。\n- 焦段：手机 2x 可减少天空和边缘杂枝，突出建筑。\n\n## 后期步骤\n\n1. 裁掉上方灰天空和右下杂枝。\n2. 提升建筑中间调和局部对比。\n3. 轻微增加穹顶绿色与墙面分离度。\n4. 远景城市略降清晰度，让主体建筑更突出。\n5. 保持色彩克制，不要强行调成艳丽风景。\n\n## 下一次练习任务\n\n拍城市建筑时练习“少天空”：同一位置拍一张天空多、一张建筑多、一张使用 2x 的主体照。比较哪张建筑最突出。\n\n## 归档路径\n\n`/Users/bytedance/Documents/摄影学习/data/archive/20260604-210301-city-church-view/`\n"
