      "critique": "# 摄影点评：湖边背影人像\n\n## 一句话总评\n\n这张照片有人物主体、湖山环境和不错的虚化分离，整体完成度较好，但人物背影姿态偏低，情绪表达还不够明确。\n\n## 评分前检查\n\n- 可见基础硬伤：没有明显手抖或严重虚焦；人物清楚，背景自然虚化。\n- 主要问题：人物头部低垂，表情和动作信息少；白衣高光略亮；右侧红色浮标有点分散。\n- 是否属于故意处理：背影人像是有效表达，但姿态还可以更明确。\n\n## 五项评分\n\n- 技术：7.0/10\n- 构图：7.0/10\n- 光线：6.8/10\n- 叙事：6.9/10\n- 总体：7.0/10\n\n## 封顶规则\n\n没有触发基础硬伤封顶。主体清晰、景深分离和环境关系都成立，可以进入 7 分段；姿态表达偏弱限制它不到 7.5。\n\n## 做得好的地方\n\n- 人物白衣和蓝色湖面有很强色彩分离。\n- 背景虚化让主体很突出。\n- 湖面和远山提供了旅行人像的环境氛围。\n\n## 优先修改项\n\n### 1. 姿态表达不够明确\n\n- 问题：人物低头背对镜头，情绪不够清楚。\n- 为什么：背影人像也需要姿态表达，比如看远方、走向水边、回头。\n- 下次怎么拍：引导人物抬头看湖，或让人物走动时抓拍。\n- 这张怎么修：裁切时保留人物面向湖面的空间，强化“看向远方”的感觉。\n\n### 2. 白衣高光略亮\n\n- 问题：白色外套局部亮度偏高，细节变薄。\n- 为什么：白衣在阳光下很容易抢过面部和环境。\n- 下次怎么拍：对白衣减 0.3 档曝光。\n- 这张怎么修：降低白色和高光，恢复衣服褶皱。\n\n### 3. 红色浮标分散注意力\n\n- 问题：右侧红点很醒目，但和人物故事关系不强。\n- 为什么：小红点会吸走视线，尤其在蓝色背景里。\n- 下次怎么拍：调整机位避开浮标，或让人物与浮标形成明确关系。\n- 这张怎么修：裁掉右侧一点，或降低红色饱和度。\n\n## 建议设置\n\n看不出真实 EXIF，以下是估计：\n\n- 户外人像：ISO 100-200。\n- 快门：1/250s 以上。\n- 光圈：若相机拍摄，f/2.8-f/4 可分离背景；手机可用人像模式或 2x。\n- 对焦：对人物头部或上半身。\n\n## 后期步骤\n\n1. 降低白衣高光。\n2. 人物头发和肩部做少量局部清晰度。\n3. 背景蓝色饱和度略降，保持自然。\n4. 右侧红色浮标降低饱和或裁掉。\n5. 轻微提升人物周围明暗对比，让主体更稳。\n\n## 下一次练习任务\n\n练习背影人像：同一场景拍三张，低头、看远方、回头。比较哪张最有情绪和故事。\n\n## 归档路径\n\n`/Users/bytedance/Documents/摄影学习/data/archive/20260604-210028-lake-back-portrait/`\n"
