      "critique": "# 摄影点评：树荫下的水面\n\n## 一句话总评\n\n这张树荫水面有清凉氛围和光影变化，但主体主次不够明确，树叶、石头、水面和暗部混在一起，观看路径偏散。\n\n## 评分前检查\n\n- 主体判断：主体是树荫下的水面和岸边环境。\n- 基础硬伤：没有严重虚焦或手抖；主要问题是构图复杂和明暗反差。\n- 意图判断：想表现树荫、水色和自然空间，意图成立但不够简化。\n\n## 五项评分\n\n- 技术：6.2/10\n- 构图：5.8/10\n- 光线：6.1/10\n- 叙事：6.0/10\n- 总体：6.0/10\n\n## 封顶规则\n\n主体可读但偏弱，画面干扰较多；光影有可取之处，所以高于普通记录，但总体不超过 6 分太多。\n\n## 做得好的地方\n\n- 水面颜色和树荫光斑有氛围。\n- 前景石头和后方水面形成了一定空间层次。\n- 暗部树影让画面有现场感，不是完全平光。\n\n## 优先修改项\n\n1. 问题：主体不够集中。\n   为什么：观众不知道你更想拍水面、光斑还是树枝。\n   下次怎么拍：选一个主题，例如“水面光斑”，然后靠近或裁切掉无关树干。\n   这张怎么修：裁掉左侧岸边和上方杂枝，集中在水面和右侧暗部倒影。\n\n2. 问题：明暗反差大。\n   为什么：左侧亮水面和右侧暗树影差距明显，细节不平衡。\n   下次怎么拍：避开正午强光，选择阴天或早晚柔光。\n   这张怎么修：高光 -25，阴影 +10，保持自然不要拉成 HDR。\n\n3. 问题：前景石头形态不够干净。\n   为什么：石头提供前景，但底部杂乱会分散注意力。\n   下次怎么拍：换更低机位，只用一块形态好看的石头做前景。\n   这张怎么修：底部略裁，减少零散石块和土面。\n\n## 建议设置\n\n看不出真实 EXIF，以下是估计：树荫水面建议 ISO 100-400、快门 1/125s 以上、光圈 f/5.6-f/8。遇到反光水面时，曝光按亮水面略降，必要时后期提暗部。\n\n## 后期步骤\n\n1. 裁掉上方杂枝和部分底部石头。\n2. 高光 -25，白色 -10。\n3. 阴影 +10，黑色略降保持深度。\n4. 绿色饱和度 -5，水面蓝绿略提亮。\n5. 给水面纹理少量增强。\n\n## 下一次练习任务\n\n拍水面时只选一个主题：倒影、光斑、波纹或岸边石头。每个主题拍 3 张，不要把所有元素都放进同一张。\n\n## 归档路径\n\n`/Users/bytedance/Documents/摄影学习/data/archive/20260604-0a436b7f/`\n"
