      "critique": "# 摄影点评：楼梯通向红门\n\n## 一句话总评\n\n这张用楼梯引导到红门，结构是明确的；但亮部偏白、树枝遮挡过多，门这个重点没有被充分强调出来。\n\n## 评分前检查\n\n- 主体判断：主体是楼梯尽头的红门和建筑入口。\n- 基础硬伤：清晰度可接受；主要问题是亮部过亮和遮挡。\n- 意图判断：楼梯作为引导线成立，属于有效构图尝试。\n\n## 五项评分\n\n- 技术：6.1/10\n- 构图：6.5/10\n- 光线：5.6/10\n- 叙事：6.2/10\n- 总体：6.3/10\n\n## 封顶规则\n\n主体可读且引导线明确；但树枝遮挡主体、墙面和台阶高光偏白，构图和光线限制了上限。\n\n## 做得好的地方\n\n- 楼梯扶手形成强引导线，视线能走向红门。\n- 红门和浅色墙面有颜色对比。\n- 竖幅适合表现入口的高度和楼梯延伸。\n\n## 优先修改项\n\n1. 问题：树枝挡住建筑入口。\n   为什么：红门是主体，遮挡会削弱终点感。\n   下次怎么拍：左右移动一步，找树枝避开门的位置；或者走近一点拍楼梯和门。\n   这张怎么修：裁掉右侧部分树木，让红门更靠近视觉中心。\n\n2. 问题：亮部偏白。\n   为什么：白墙和台阶过亮会让画面显得薄，细节也变少。\n   下次怎么拍：曝光补偿 -0.3 到 -0.7EV，保护白墙和台阶。\n   这张怎么修：高光 -30，白色 -15，台阶局部增加纹理。\n\n3. 问题：底部空地占比偏大。\n   为什么：空地没有足够信息，会拖慢视线进入楼梯。\n   下次怎么拍：镜头稍微向上或往前走，减少底部空地。\n   这张怎么修：裁掉底部约 10%-15%。\n\n## 建议设置\n\n看不出真实 EXIF，以下是估计：白天建筑入口建议 ISO 100-400、快门 1/125s 以上、光圈 f/5.6-f/8。手机拍摄时点按白墙和红门之间的中间调测光，曝光略降。\n\n## 后期步骤\n\n1. 裁掉底部空地和右侧部分树木。\n2. 高光 -30，白色 -15。\n3. 阴影 +10，恢复门和树下暗部。\n4. 红色饱和度 +5，让门更突出。\n5. 台阶和扶手加少量清晰度。\n\n## 下一次练习任务\n\n拍 5 张“楼梯通向某物”：每张都让楼梯终点是明确主体，比如门、窗、人或光。拍完检查终点有没有被遮挡。\n\n## 归档路径\n\n`/Users/bytedance/Documents/摄影学习/data/archive/20260604-1326da7c/`\n"
