      "critique": "# 摄影点评：节日场景人像拼图\n\n## 一句话总评\n\n这张拼图有热闹的节日氛围和自然的人物状态，但闪光灯太直、画面拼接分散了注意力，更像生活记录而不是完成度很高的人像作品。\n\n## 评分前检查\n\n- 可见基础硬伤：没有严重手抖或完全对焦失败；人物面部可辨。\n- 主要问题：上下两张拼接导致中心不统一；直闪让人物和玩偶偏硬，背景灯光层次被压平。\n- 是否属于故意处理：拼接应是展示选择，但从摄影评价看，它削弱了单张照片的构图完整性。\n\n## 五项评分\n\n- 技术：5.8/10\n- 构图：5.3/10\n- 光线：5.4/10\n- 叙事：6.3/10\n- 总体：5.7/10\n\n## 封顶规则\n\n没有触发严重基础硬伤封顶，因为人物清楚、场景可辨。但拼图形式、直闪和杂乱背景让它更接近生活记录，总体不宜超过 6 分出头。\n\n## 做得好的地方\n\n- 场景有节日元素，红色、灯串、玩偶能传达热闹气氛。\n- 人物表情自然，尤其下半张的眼神更稳定。\n- 近距离拍摄让人与玩偶有互动，不是完全旁观式记录。\n\n## 优先修改项\n\n### 1. 拼图让视觉中心变散\n\n- 问题：上下两张照片并列后，观众不知道该先看上面的人物互动，还是下面的正面人像。\n- 为什么：摄影点评更看重单张画面的主次关系；拼图会降低构图完整性。\n- 下次怎么拍：先选一个明确目标：要拍“人和玩偶互动”，还是“节日氛围人像”。\n- 这张怎么修：建议只保留下半张作为主图，再单独裁切和调整；上半张可以作为备选记录。\n\n### 2. 闪光灯太直接\n\n- 问题：人物脸部和白色衣服被直闪打亮，背景灯串的暖光氛围被削弱。\n- 为什么：夜景人像最重要的是保留环境光，直闪会让前景亮、背景暗，画面显得硬。\n- 下次怎么拍：如果用手机，尝试关闭闪光灯，找一个灯串或店铺光作为侧前方补光；人物脸朝向光源。\n- 这张怎么修：降低人物高光和白色衣服亮度，背景暖色灯串可以略微提亮。\n\n### 3. 背景元素太多\n\n- 问题：玩偶、树枝、灯串、装饰物都很抢眼，人物面部没有绝对优势。\n- 为什么：人像里背景可以丰富，但不能和脸争夺第一注意力。\n- 下次怎么拍：让人物离背景远一点，使用人像模式或更长焦段压缩背景。\n- 这张怎么修：给人物脸部做轻微局部提亮，降低边缘装饰物的清晰度和亮度。\n\n## 建议设置\n\n看不出真实 EXIF，以下是估计：\n\n- 夜景人像：尽量关闭直闪，优先使用现场灯光。\n- ISO：手机可接受自动；相机可从 ISO 800-1600 起试。\n- 快门：人物静止时至少 1/80s；动作多时 1/125s 以上。\n- 光圈：相机可用 f/1.8-f/2.8；手机用人像模式时注意边缘抠图。\n\n## 后期步骤\n\n1. 先决定只保留一张，不建议把两张作为同一张摄影作品评价。\n2. 如果保留下半张，裁掉左上角过大的牌子和部分边缘杂物。\n3. 降低白衣服和脸部高光，避免直闪感过强。\n4. 提升背景暖色灯串亮度和饱和度，让节日氛围回来。\n5. 人物眼睛和面部做少量局部锐化，背景不要过度锐化。\n\n## 下一次练习任务\n\n拍一组夜景人像时，固定同一场景拍三张：直闪一张、关闭闪光灯一张、让人物靠近暖光源一张。比较哪一张脸更自然、背景氛围更完整。\n\n## 归档路径\n\n`/Users/bytedance/Documents/摄影学习/data/archive/20260604-3a548716/`\n"
